import { describe, expect, it } from 'vitest';
import { resolveLegacyMeetingRedirect } from './_shared';
import duplicateStoryRedirects from './duplicate-story-redirects.json';

// 2026-10-14, see .claude/state.md's "meeting 12940/13790" and the 10
// Moreno Valley pairs found the same round -- a real eSCRIBE content_hash
// bug let the same real meeting get scraped twice under two different
// hashes, producing two `stories` rows. Generated by
// scripts/generate_duplicate_story_redirects.py straight from
// stories.superseded_by_slug (same pattern as event-series-redirects.json/
// legacy-meeting-redirects.json now) -- this file still asserts the map's
// shape directly, not just the lookup mechanics (already fully covered
// generically, see legacy-meeting-redirect.test.ts).

describe('duplicate-story-redirects.json', () => {
  it('is a non-empty map of old meeting-story slugs to canonical meeting-story slugs', () => {
    const entries = Object.entries(duplicateStoryRedirects as Record<string, string>);
    expect(entries.length).toBeGreaterThan(0);
    for (const [oldSlug, canonicalSlug] of entries) {
      expect(oldSlug).toMatch(/^meeting-/);
      expect(canonicalSlug).toMatch(/^meeting-/);
      expect(canonicalSlug).not.toBe(oldSlug);
    }
  });

  it('resolves the real 12940/13790 entry to its canonical /s/ path', () => {
    const path = resolveLegacyMeetingRedirect(
      '/s/meeting-2026-09-24-12940/', duplicateStoryRedirects as Record<string, string>,
    );
    expect(path).toBe('/s/meeting-2026-09-24-13790/');
  });

  // 2026-10-21 (Kö 6 cleanup): two duplicate stories that were still live.
  it.each([
    ['meeting-2026-08-27-14970', 'meeting-2026-08-27-13780'],
    ['meeting-2026-10-13-14586', 'meeting-2026-10-13-14192'],
  ])('301s the formerly live duplicate %s to %s', (oldSlug, canonicalSlug) => {
    const map = duplicateStoryRedirects as Record<string, string>;
    expect(resolveLegacyMeetingRedirect(`/s/${oldSlug}/`, map)).toBe(`/s/${canonicalSlug}/`);
    // no chain: a canonical slug is never itself redirected
    expect(map[canonicalSlug]).toBeUndefined();
  });
});
